package android.widget;import android.content.Context;import android.view.View;import android.view.ViewGroup;public class LinearLayout extends ViewGroup {public static final int HORIZONTAL=0,VERTICAL=1;public static class LayoutParams extends ViewGroup.MarginLayoutParams {public LayoutParams(int width,int height){super(width,height);}}public int orientation=HORIZONTAL,gravity;public LinearLayout(Context context){super(context);}public void setOrientation(int value){hit("LinearLayout.setOrientation");orientation=value;done("LinearLayout.setOrientation");}public void setGravity(int value){hit("LinearLayout.setGravity");gravity=value;done("LinearLayout.setGravity");}@Override protected void onLayout(boolean changed,int l,int t,int r,int b){int x=0,y=0;for(View child:hostChildren()){child.layout(x,y,x+child.getMeasuredWidth(),y+child.getMeasuredHeight());if(orientation==HORIZONTAL)x+=child.getMeasuredWidth();else y+=child.getMeasuredHeight();}}}
